mapper.update:
UPDATE user_chat
SET isActive = 0
WHERE seqChattingroom = #{roomId}
  AND seqMember = #{userId}

mapper.insert:
INSERT INTO poll_content (
    seq,
    seqPoll,
    pollContent
) VALUES (
    seqPollContent.NEXTVAL,
    #{seqPoll},
    #{pollContent}
)

INSERT INTO poll_result (
    seq,
    seqPollContent,
    seqMember
) VALUES (
    seqPollResult.NEXTVAL,
    #{pollContentId},
    #{seqMember}
)

mapper.delete:
DELETE FROM poll_result
WHERE seqMember = #{seqMember}
  AND seqPollContent IN (
      SELECT seq
      FROM poll_content
      WHERE seqPoll = #{pollId}
  )

DELETE FROM poll_result
WHERE seqPollContent IN (
    SELECT seq
    FROM poll_content
    WHERE seqPoll = #{pollId}
)

mapper.select:
SELECT seqTravelPost
FROM chattingroom
WHERE seq = #{roomId}

SELECT seq FROM (
    SELECT cr.seq
    FROM chattingroom cr
        INNER JOIN user_chat uc1
            ON cr.seq = uc1.seqChattingroom AND uc1.seqMember = #{me}
        INNER JOIN user_chat uc2
            ON cr.seq = uc2.seqChattingroom AND uc2.seqMember = #{target}
    WHERE cr.category = 1
) WHERE ROWNUM = 1

mapper.update:
UPDATE routine
SET
    title = #{title},
    detail = #{detail},
    seqLocation = #{seqLocation}
WHERE seq = #{seq}

